engine.add_casefact('kb', 'is_big', ('Bob', True))
engine.add_casefact('kb', 'is_cold', ('Bob', True))
engine.add_casefact('kb', 'is_furry', ('Bob', True))
engine.add_casefact('kb', 'is_smart', ('Bob', True))

